-- Trae ai-agent database fixture, step 0: the schema Trae's chat tables have,
-- two projects, two sessions and the first turns. Every statement is one line,
-- and every table the reader does not need is present anyway so the fixture
-- resembles a real database: chat_message_general and user_configuration hold
-- conversation text and must never be read.
CREATE TABLE project (id integer NOT NULL PRIMARY KEY AUTOINCREMENT, project_id text NOT NULL, source text NOT NULL DEFAULT 'native-ide', user_id text NOT NULL, name text, absolute_path text, workspace_type text NOT NULL DEFAULT 'single_root', workspace_folders text NOT NULL DEFAULT '[]', deleted_at bigint)
CREATE TABLE chat_session (id integer NOT NULL PRIMARY KEY AUTOINCREMENT, session_id text NOT NULL, project_id text NOT NULL, created_at bigint NOT NULL DEFAULT (strftime('%s','now')), updated_at bigint NOT NULL DEFAULT (strftime('%s','now')), deleted_at bigint NOT NULL DEFAULT 0, session_type text NOT NULL DEFAULT 'side_chat', session_title text NOT NULL DEFAULT '', worktree_id text NOT NULL DEFAULT '', context text NOT NULL DEFAULT '{}')
CREATE TABLE chat_turn (id integer NOT NULL PRIMARY KEY AUTOINCREMENT, session_id text NOT NULL, turn_id text NOT NULL, reply_to_message_id text NOT NULL DEFAULT '', response_message_id text NOT NULL DEFAULT '', requirement_id text NOT NULL DEFAULT '', rewritten_user_message text NOT NULL DEFAULT '', turn_status text NOT NULL, error_message text NOT NULL DEFAULT '', context text NOT NULL, created_at bigint NOT NULL DEFAULT (strftime('%s','now')), updated_at bigint NOT NULL DEFAULT (strftime('%s','now')), deleted_at bigint NOT NULL DEFAULT 0, agent_type text NOT NULL DEFAULT 'builder', agent_id text NOT NULL DEFAULT '', agent_name text NOT NULL DEFAULT '')
CREATE TABLE chat_message (id integer NOT NULL PRIMARY KEY AUTOINCREMENT, session_id text NOT NULL, message_id text NOT NULL, message_type text NOT NULL, message_role text NOT NULL, user_message_context text NOT NULL DEFAULT '', created_at bigint NOT NULL DEFAULT (strftime('%s','now')), deleted_at bigint NOT NULL DEFAULT 0)
CREATE TABLE chat_message_general (id integer NOT NULL PRIMARY KEY AUTOINCREMENT, message_id text NOT NULL, content text NOT NULL DEFAULT '', created_at bigint NOT NULL DEFAULT (strftime('%s','now')), deleted_at bigint NOT NULL DEFAULT 0)
CREATE TABLE history_v2 (id integer NOT NULL PRIMARY KEY AUTOINCREMENT, history_v2_id text NOT NULL, session_id text NOT NULL, message_id text NOT NULL DEFAULT '', messages text NOT NULL DEFAULT '', token_usage integer NOT NULL DEFAULT 0, summary text, created_at bigint NOT NULL DEFAULT (strftime('%s','now')), deleted_at bigint NOT NULL DEFAULT 0)
CREATE TABLE user_configuration (id integer NOT NULL PRIMARY KEY AUTOINCREMENT, key text NOT NULL, value text NOT NULL DEFAULT '')
