INSERT INTO chat_turn (session_id, turn_id, turn_status, context, created_at, deleted_at) VALUES ('sess-alpha', 'turn-2', 'completed', '{"chat_start_time":1792114200000,"token_usage":{"prompt_tokens":1000,"completion_tokens":200,"total_tokens":1200,"reasoning_tokens":0,"cache_creation_input_tokens":300,"cache_read_input_tokens":0},"persist_user_message_context":{"model_info":{"config_name":"kimi-k2","model_name":"kimi-k2__max","display_model_name":"Kimi K2"}}}', 1792114200, 0)
